import math


def reduce_fraction(numerator, denominator):
    if denominator == 0:
        raise ValueError("zero denominator")
    divisor = math.gcd(numerator, denominator) * (-1 if denominator < 0 else 1)
    return numerator // divisor, denominator // divisor

